#!/usr/bin/env node
// Computes holiday dates from design/holidays.json (fixed dates, nth weekdays,
// and Hebrew / Islamic (Umm al-Qura) calendar dates via ICU) and writes the
// catalog for the backend, Android and iOS.
//
//   node design/generate-holidays.mjs           # write files
//   node design/generate-holidays.mjs --check   # verify generated files are up to date

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const spec = JSON.parse(readFileSync(join(root, "design/holidays.json"), "utf8"));
const checkOnly = process.argv.includes("--check");
const [firstYear, lastYear] = spec.years;
const LANGS = ["en", "he", "ar", "ru"];

const OUT = {
  ts: join(root, "backend/functions/src/lib/holidays.generated.ts"),
  kotlin: join(root, "android/core/model/src/main/kotlin/com/thinkofme/core/model/Holidays.kt"),
  swift: join(root, "ios/Packages/Core/Sources/Core/Generated/Holidays.swift"),
};

const DAY = 86_400_000;
const iso = (t) => new Date(t).toISOString().slice(0, 10);
const hebrew = new Intl.DateTimeFormat("en-u-ca-hebrew", { timeZone: "UTC", day: "numeric", month: "long" });
const islamic = new Intl.DateTimeFormat("en-u-ca-islamic-umalqura", { timeZone: "UTC", day: "numeric", month: "numeric" });
const parts = (fmt, t) => Object.fromEntries(fmt.formatToParts(new Date(t)).map((p) => [p.type, p.value]));

function datesFor(rule) {
  const out = [];
  for (let year = firstYear; year <= lastYear; year++) {
    switch (rule.type) {
      case "fixed":
        out.push(iso(Date.UTC(year, rule.month - 1, rule.day)));
        break;
      case "nthWeekday": {
        if (rule.nth > 0) {
          const first = new Date(Date.UTC(year, rule.month - 1, 1));
          const offset = (rule.weekday - first.getUTCDay() + 7) % 7;
          out.push(iso(Date.UTC(year, rule.month - 1, 1 + offset + (rule.nth - 1) * 7)));
        } else {
          const last = new Date(Date.UTC(year, rule.month, 0));
          const offset = (last.getUTCDay() - rule.weekday + 7) % 7;
          out.push(iso(last.getTime() - offset * DAY));
        }
        break;
      }
      case "hebrew":
      case "islamic": {
        // Lunar dates: scan the Gregorian year (a few Islamic holidays fall twice in one year).
        for (let t = Date.UTC(year, 0, 1); t < Date.UTC(year + 1, 0, 1); t += DAY) {
          const p = parts(rule.type === "hebrew" ? hebrew : islamic, t);
          if (String(p.month) === String(rule.month) && Number(p.day) === rule.day) out.push(iso(t));
        }
        break;
      }
      default:
        throw new Error(`Unknown rule ${rule.type}`);
    }
  }
  return out;
}

const holidays = spec.holidays.map((h) => {
  for (const lang of LANGS) if (!h.name[lang]) throw new Error(`${h.id} is missing a ${lang} name`);
  const dates = datesFor(h.rule);
  if (dates.length < lastYear - firstYear) throw new Error(`${h.id}: too few dates (${dates.length})`);
  return { ...h, dates };
});

const header = "GENERATED by design/generate-holidays.mjs from design/holidays.json. Do not edit by hand.";
const q = (s) => JSON.stringify(s);

const ts = `// ${header}
/* eslint-disable */
import type { Locale } from "./messages";

export interface HolidayDef {
  id: string;
  audience: "couple" | "everyone";
  defaults: readonly Locale[];
  name: Readonly<Record<Locale, string>>;
  /** ISO dates (YYYY-MM-DD), ${firstYear}–${lastYear}. */
  dates: readonly string[];
}

export const HOLIDAYS: readonly HolidayDef[] = ${JSON.stringify(
  holidays.map(({ id, audience, defaults, name, dates }) => ({ id, audience, defaults, name, dates })),
  null,
  2,
)};
`;

const kotlin = `// ${header}
@file:Suppress("MaxLineLength")

package com.thinkofme.core.model

import java.time.LocalDate

enum class HolidayAudience { COUPLE, EVERYONE }

/** A gift-giving holiday with precomputed dates (${firstYear}–${lastYear}). */
data class Holiday(
    val id: String,
    val audience: HolidayAudience,
    val defaultLanguages: Set<String>,
    private val names: Map<String, String>,
    private val isoDates: List<String>,
) {
    val dates: List<LocalDate> by lazy { isoDates.map(LocalDate::parse) }

    /** Name in the given app language, falling back to English. */
    fun name(language: String): String = names[if (language == "iw") "he" else language] ?: names.getValue("en")

    fun nextDate(today: LocalDate): LocalDate? = dates.firstOrNull { !it.isBefore(today) }
}

object Holidays {
    val all: List<Holiday> = listOf(
${holidays.map((h) => `        Holiday(
            ${q(h.id)},
            HolidayAudience.${h.audience.toUpperCase()},
            setOf(${h.defaults.map(q).join(", ")}),
            mapOf(${LANGS.map((l) => `${q(l)} to ${q(h.name[l])}`).join(", ")}),
            listOf(${h.dates.map(q).join(", ")}),
        ),`).join("\n")}
    )

    fun byId(id: String): Holiday? = all.firstOrNull { it.id == id }

    /** Holidays that are on by default for an app language. */
    fun defaultsFor(language: String): Set<String> {
        val lang = if (language == "iw") "he" else language
        return all.filter { lang in it.defaultLanguages }.map { it.id }.toSet().ifEmpty { all.filter { "en" in it.defaultLanguages }.map { it.id }.toSet() }
    }
}
`;

const swift = `// ${header}

import Foundation

public enum HolidayAudience: String, Sendable { case couple, everyone }

/// A gift-giving holiday with precomputed dates (${firstYear}–${lastYear}).
public struct Holiday: Identifiable, Sendable {
    public let id: String
    public let audience: HolidayAudience
    public let defaultLanguages: Set<String>
    let names: [String: String]
    let isoDates: [String]

    /// Name in the given app language, falling back to English.
    public func name(language: String) -> String { names[language] ?? names["en"] ?? id }

    public var dates: [Date] {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withFullDate]
        formatter.timeZone = .current
        return isoDates.compactMap { formatter.date(from: $0) }
    }

    public func nextDate(from today: Date, calendar: Calendar = .current) -> Date? {
        let start = calendar.startOfDay(for: today)
        return dates.first { $0 >= start }
    }
}

public enum Holidays {
    public static let all: [Holiday] = [
${holidays.map((h) => `        Holiday(
            id: ${q(h.id)},
            audience: .${h.audience},
            defaultLanguages: [${h.defaults.map(q).join(", ")}],
            names: [${LANGS.map((l) => `${q(l)}: ${q(h.name[l])}`).join(", ")}],
            isoDates: [${h.dates.map(q).join(", ")}]
        ),`).join("\n")}
    ]

    public static func byId(_ id: String) -> Holiday? { all.first { $0.id == id } }

    /// Holidays that are on by default for an app language.
    public static func defaults(forLanguage language: String) -> Set<String> {
        let ids = Set(all.filter { $0.defaultLanguages.contains(language) }.map(\\.id))
        return ids.isEmpty ? Set(all.filter { $0.defaultLanguages.contains("en") }.map(\\.id)) : ids
    }
}
`;

let stale = false;
for (const [path, content] of [[OUT.ts, ts], [OUT.kotlin, kotlin], [OUT.swift, swift]]) {
  if (checkOnly) {
    if (!existsSync(path) || readFileSync(path, "utf8") !== content) {
      console.error(`Out of date: ${path}`);
      stale = true;
    }
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${path.replace(root + "/", "")}`);
  }
}
if (stale) {
  console.error("Run: node design/generate-holidays.mjs");
  process.exit(1);
}
